//! Canonical select and textarea readonly type metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><select id=select><option value=one>One</option></select><select id=multiple multiple><option>Many</option></select><select id=list size=4><option>List</option></select><textarea id=textarea>seed</textarea></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://control-type.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn control_type_canonical_metadata_and_descriptors(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var select=document.getElementById('select'),multiple=document.getElementById('multiple'),list=document.getElementById('list'),textarea=document.getElementById('textarea'),types=[HTMLSelectElement,HTMLTextAreaElement],items=[select,textarea];for(var i=0;i<2;i++){var a=Object.getOwnPropertyDescriptor(types[i].prototype,'type');if(!a||typeof a.get!=='function'||a.set!==undefined||!a.enumerable||!a.configurable||a.get.name!=='get type'||a.get.length!==0||Object.hasOwn(items[i],'type'))throw 'canonical readonly type descriptor';}if(select.type!=='select-one'||multiple.type!=='select-multiple'||list.type!=='select-one'||textarea.type!=='textarea'||select.value!=='one'||textarea.value!=='seed')throw 'native type metadata';"#);}
#[test]
fn control_type_inert_exact_presence_and_namespaces(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var html='http://www.w3.org/1999/xhtml',doc=new Document(),s=doc.createElementNS(html,'select'),t=doc.createElementNS(html,'textarea');if(s.type!=='select-one'||t.type!=='textarea')throw 'inert type';s.setAttributeNS('urn:foreign','x:multiple','');s.setAttributeNS(null,'MULTIPLE','');if(s.type!=='select-one')throw 'exact attribute namespace and case';s.setAttributeNS(null,'multiple','false');if(s.type!=='select-multiple'||s.cloneNode(false).type!=='select-multiple')throw 'presence not value';s.removeAttributeNS(null,'multiple');if(s.type!=='select-one')throw 'live native presence';t.setAttribute('type','wrong');if(t.type!=='textarea')throw 'fixed textarea type';"#);}
#[test]
fn control_type_readonly_concrete_brands_and_author_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var items=[document.getElementById('select'),document.getElementById('textarea')],types=[HTMLSelectElement,HTMLTextAreaElement],values=['select-one','textarea'],calls=0;for(var i=0;i<2;i++){var c=items[i],get=Object.getOwnPropertyDescriptor(types[i].prototype,'type').get;c.type={toString:function(){calls++;return 'bad';}};if(c.type!==values[i])throw 'readonly sloppy';var caught=false;try{(function(){'use strict';c.type='bad';})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'readonly strict';for(var bad of [{},Object.create(types[i].prototype),items[1-i],document.createElementNS('urn:foreign',i?'textarea':'select')]){caught=false;try{get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'concrete type brand';}Object.defineProperty(c,'type',{value:'author',configurable:true});if(c.type!=='author'||get.call(c)!==values[i])throw 'native authority';delete c.type;if(c.type!==values[i])throw 'native restore';}if(calls)throw 'readonly conversion';"#);}

#[test]
fn control_type_inert_adoption_live_presence_and_author_getters(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var html='http://www.w3.org/1999/xhtml',doc=new Document(),other=new Document(),s=doc.createElementNS(html,'select'),t=doc.createElementNS(html,'textarea'),get=Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'type').get;s.setAttribute('multiple','\ud800');Object.defineProperty(s,'hasAttribute',{value:function(){throw 'author presence';}});Object.defineProperty(s,'getAttribute',{value:function(){throw 'author value';}});Object.defineProperty(s,'multiple',{get:function(){throw 'author IDL';}});if(get.call(s)!=='select-multiple')throw 'native presence';if(other.adoptNode(s)!==s||s.type!=='select-multiple'||other.adoptNode(t)!==t||t.type!=='textarea')throw 'adopted metadata';var copy=s.cloneNode(false);if(copy.type!=='select-multiple')throw 'cloned metadata';s.removeAttribute('multiple');if(s.type!=='select-one'||copy.type!=='select-multiple')throw 'live independent presence';var upper=doc.createElementNS(html,'SELECT'),foreign=doc.createElementNS('urn:foreign','select'),caught=0;for(var bad of [upper,foreign]){try{get.call(bad);}catch(e){if(e instanceof TypeError)caught++;}}if(caught!==2)throw 'exact namespace local brand';"#);}
#[test]
fn control_type_saved_child_origin_precedes_result_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var s=document.getElementById('select'),t=document.getElementById('textarea'),a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLSelectElement.prototype,'type').get,b=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLTextAreaElement.prototype,'type').get;if(a.call(s)!=='select-one'||b.call(t)!=='textarea')throw 'captured getter';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.set_location(&crate::navigation::address("https://other-control-type.test/",&crate::navigation::Location::home()).unwrap());for source in ["a.call(s);","b.call(t);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);}p.set_location(&crate::navigation::address("https://control-type.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(a.call(s)!=='select-one'||b.call(t)!=='textarea')throw 'captured origin recovery';");}
#[test]
fn control_type_native_paid_reads_refuse_and_recover(){for &(interface,method) in script_control_type::GETTERS{for mode in 0..4{let(mut d,mut f,mut p)=fixture();let id=if interface=="HTMLSelectElement"{"select"}else{"textarea"};let expected=if interface=="HTMLSelectElement"{"select-one"}else{"textarea"};let n=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()==id)).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=expected.len()-1,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_type_get(node_handle(n),method).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.limits.host.string_bytes=expected.len();p.state.retained_limit=p.state.retained;p.begin_job();p.state.copy_work=expected.len();let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_type_get(node_handle(n),method).unwrap();assert!(matches!(value,Value::String(v)if v==expected));assert_eq!(p.state.copy_work,0);assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}}}
#[test]
fn control_type_inert_paid_reads_refuse_and_recover(){for tag in ["select","textarea"]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();let source=format!("var el=new Document().createElementNS('http://www.w3.org/1999/xhtml','{tag}'),read=Object.getOwnPropertyDescriptor({}.prototype,'type').get;read.call(el);",if tag=="select"{"HTMLSelectElement"}else{"HTMLTextAreaElement"});run(&mut d,&mut f,&mut p,&source);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=7,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("read.call(el);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.limits.host.string_bytes=1024;p.begin_job();run(&mut d,&mut f,&mut p,if tag=="select"{"if(read.call(el)!=='select-one')throw 'inert recovery';"}else{"if(read.call(el)!=='textarea')throw 'inert recovery';"});}}}

#[test]
fn control_type_presence_never_copies_raw_attribute_payload(){let(mut d,mut f,mut p)=fixture();let n=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="multiple")).unwrap();if let NodeKind::Element{attrs,..}=&mut d.nodes[n].kind{let a=attrs.iter_mut().find(|a|a.name.html_is("multiple")).unwrap();a.value=DomString::from_units(&vec![0xd800;4096],usize::MAX).unwrap();}else{panic!("select")};p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();p.state.limits.host.string_bytes=15;p.state.copy_work=15;p.state.retained_limit=p.state.retained;let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_type_get(node_handle(n),script_control_type::GETTERS[0].1).unwrap();assert!(matches!(value,Value::String(value)if value=="select-multiple"));assert_eq!(p.state.copy_work,0);assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}
